mapper.sql:
FROM (
    SELECT o.id AS order_id, o.no AS order_no, o.order_type, o.brand, o.status, o.merch_id, i.style_id,
           SUM(i.qty) AS qty, SUM(i.scheduled_qty) AS scheduled_qty, SUM(i.returned_qty) AS returned_qty,
           bool_or(i.scheduled_qty < i.qty) AS short_scheduled, bool_or(i.returned_qty < i.qty) AS short_returned,
           LEAST(COALESCE(o.commit_date, o.required_date), MIN(i.line_due_date)) AS due_date
    FROM ord_order o
    JOIN ord_order_item i ON i.order_id = o.id AND i.qty > 0
    WHERE o.status IN ('APPROVED', 'RUNNING')
    AND o.product_line = ANY(#{scope.lines.values, typeHandler=com.lingmao.scm.common.mybatis.StringArrayTypeHandler})
    AND (o.create_by = #{scope.userId} OR o.sales_id = #{scope.userId} OR o.merch_id = #{scope.userId})
    AND o.product_line = #{q.productLine}
    AND o.brand = #{q.brand}
    AND o.order_type = #{q.orderType}
    AND o.sales_id = #{q.salesId}
    AND o.merch_id = #{q.merchId}



        AND (upper(o.no) LIKE #{keywordCode}
             OR upper(o.no) IN #{code}
             OR i.style_id IN (SELECT ks.id FROM sty_style ks WHERE upper(ks.code) LIKE #{keywordCode}
                 OR upper(ks.code) IN #{code}))

    GROUP BY o.id, i.style_id
) g
JOIN sty_style s ON s.id = g.style_id
CROSS JOIN LATERAL (
    SELECT g.due_date < #{today} AND g.short_returned AS late,
           g.due_date BETWEEN #{today} AND #{nearUntil} AND g.short_returned AS near,
           g.short_scheduled AS unscheduled
) f
CROSS JOIN LATERAL (
    SELECT COALESCE(bool_or(EXISTS (SELECT 1 FROM prd_node n
                                    WHERE n.prd_order_id = p.id AND n.actual_finish IS NULL AND n.plan_finish < #{today})), false) AS node_late,
           COALESCE(bool_or(EXISTS (SELECT 1 FROM prd_issue x WHERE x.prd_order_id = p.id AND x.status <> 'CLOSED')), false) AS issue,
           COALESCE(bool_or(COALESCE(p.expect_date, p.due_date) <= #{nearUntil}), false) AS due_soon
    FROM prd_order p
    WHERE p.order_id = g.order_id AND p.style_id = g.style_id AND p.status IN ('APPROVED', 'RUNNING')
) pr
WHERE true
AND g.due_date >= #{q.dueDateFrom}
AND g.due_date <= #{q.dueDateTo}
